#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>
using namespace std;

const int N = 33;
const long long mod = 1000000007;

struct Matrix {
    long long a[N][N];
    int size;
    void toZero() {
        memset(a, 0, sizeof(a));
    }
    void toIdentity() {
        toZero();
        for (int i = 0; i < size; ++i)
            a[i][i] = 1;
    }
    Matrix operator*(const Matrix &b) const {
        Matrix res;
        res.size = size;
        res.toZero();
        for (int i = 0; i < size; ++i)
            for (int j = 0; j < size; ++j)
                for (int k = 0; k < size; ++k)
                    res.a[i][j] = (res.a[i][j] + a[i][k] * b.a[k][j]) % mod;
        return res;
    }
};

long long n, K;
int r;
vector<Matrix> one, two, rotr, rotc;

long long readInt() {
    long long x;
    cin >> x;
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    n = readInt();
    K = readInt();
    r = K + 1;

    one.resize(r);
    two.resize(r);
    rotr.resize(r);
    rotc.resize(r);

    // Initialize 'one' matrices
    for (int i = 0; i < r; ++i) {
        one[i].size = r;
        one[i].toZero();
        for (int j = 0; j < r; ++j)
            one[i].a[i][j] = 1;
        if (i > 0) {
            for (int j = 0; j < r; ++j)
                one[i].a[i][j] = 1;
        }
    }

    // Initialize 'rotr' matrices
    for (int i = 0; i < r; ++i) {
        rotr[i].size = r;
        rotr[i].toZero();
        if (i == 1) {
            rotr[i].toZero();
            rotr[i].a[0][0] = 1;
            rotr[i].a[1][K] = 1;
            for (int j = 2; j <= K; ++j)
                rotr[i].a[j][j - 1] = 1;
        } else if (i > 1) {
            rotr[i] = rotr[1] * rotr[i - 1];
        } else {
            rotr[i].toIdentity();
        }
    }

    // Initialize 'rotc' matrices
    for (int i = 0; i < r; ++i) {
        rotc[i].size = r;
        rotc[i].toZero();
        if (i == 1) {
            rotc[i].toZero();
            rotc[i].a[0][0] = 1;
            rotc[i].a[K][1] = 1;
            for (int j = 2; j <= K; ++j)
                rotc[i].a[j - 1][j] = 1;
        } else if (i > 1) {
            rotc[i] = rotc[i - 1] * rotc[1];
        } else {
            rotc[i].toIdentity();
        }
    }

    // Initialize 'two' matrices
    two[1].size = r;
    two[1].toIdentity();
    for (int i = 1; i <= K; ++i)
        two[1] = one[i] * two[1];

    // Convert n to base K
    vector<long long> num;
    long long tempN = n;
    while (tempN > 0) {
        num.push_back(tempN % K);
        tempN /= K;
    }
    reverse(num.begin(), num.end());

    // Build 'two' matrices for higher powers
    for (int i = 2; i < (int)num.size(); ++i) {
        two[i].size = r;
        two[i].toIdentity();
        for (int j = 0; j < K; ++j)
            two[i] = rotr[j] * two[i - 1] * rotc[j] * two[i];
    }

    // Multiply matrices according to the base-K representation
    Matrix result;
    result.size = r;
    result.toIdentity();

    int ps = 0;
    for (size_t i = 0; i < num.size(); ++i) {
        long long count = num[i];
        if (i == num.size() - 1) {
            for (long long j = 0; j < count; ++j) {
                result = one[ps % K + 1] * result;
                ps++;
            }
        } else {
            for (long long j = 0; j < count; ++j) {
                result = rotr[ps % K] * two[(int)num.size() - i - 2] * rotc[ps % K] * result;
                ps++;
            }
        }
    }

    long long res = 1;
    for (int i = 1; i <= K; ++i) {
        for (int j = 0; j < r; ++j)
            res = (res + result.a[i][0]) % mod;
    }

    cout << res % mod << "\n";

    return 0;
}
